-- Hand-written. Not generated by drizzle-kit — do not regenerate over this file.
--
-- Three things Drizzle does not model, all of which are security or correctness
-- invariants rather than structure:
--
--   1. Row-level security on every table (PLAN §11).
--   2. Tenant-integrity composite foreign keys, which close a hole RLS alone
--      leaves open (see below).
--   3. The deferred zero-sum constraint trigger for double-entry (PLAN D1).

-- ── 1. Tenant integrity ─────────────────────────────────────────────────────
--
-- RLS stops user B from *reading* user A's rows, but foreign-key checks run
-- with RLS bypassed. Without the composite keys below, B could insert an entry
-- carrying `user_id = B` that references A's `transaction_id`. B cannot see the
-- result, but the zero-sum trigger sums every entry for that transaction
-- regardless of owner — so B could unbalance A's ledger, or block A's writes.
--
-- Making (id, user_id) the referenced key forces every child row to belong to
-- the same tenant as its parent, structurally.

ALTER TABLE "transactions" ADD CONSTRAINT "transactions_id_user_key" UNIQUE ("id", "user_id");
--> statement-breakpoint
ALTER TABLE "accounts" ADD CONSTRAINT "accounts_id_user_key" UNIQUE ("id", "user_id");
--> statement-breakpoint
ALTER TABLE "instruments" ADD CONSTRAINT "instruments_id_user_key" UNIQUE ("id", "user_id");
--> statement-breakpoint

ALTER TABLE "entries" DROP CONSTRAINT "entries_transaction_id_transactions_id_fk";
--> statement-breakpoint
