-- ── 2. Double-entry zero-sum ────────────────────────────────────────────────
--
-- Deferred to COMMIT because a balanced transaction is necessarily unbalanced
-- part-way through inserting its own entries.

CREATE OR REPLACE FUNCTION "public"."assert_transaction_balanced"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $fn$
DECLARE
  v_txn   uuid;
  v_sum   bigint;
  v_count integer;
BEGIN
  v_txn := COALESCE(NEW."transaction_id", OLD."transaction_id");

  SELECT COALESCE(SUM("amount_hkd_minor"), 0), COUNT(*)
    INTO v_sum, v_count
    FROM "public"."entries"
   WHERE "transaction_id" = v_txn;

  -- Zero entries means the parent transaction was deleted and its entries
  -- cascaded. Nothing to balance.
  IF v_count = 0 THEN
    RETURN NULL;
  END IF;

  IF v_count < 2 THEN
    RAISE EXCEPTION
      'transaction % has % entry: double-entry requires at least 2', v_txn, v_count
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_sum <> 0 THEN
    RAISE EXCEPTION
      'transaction % entries sum to % HKD minor units, must be 0', v_txn, v_sum
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$fn$;
--> statement-breakpoint

CREATE CONSTRAINT TRIGGER "entries_balanced"
  AFTER INSERT OR UPDATE OR DELETE ON "entries"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  EXECUTE FUNCTION "public"."assert_transaction_balanced"();
--> statement-breakpoint

-- ── 3. Row-level security ───────────────────────────────────────────────────
--
-- Applied by loop over an explicit table list. The list is visible for review,
-- and the loop guarantees no table gets a hand-typed policy that quietly
-- differs from the others — missing or divergent policies being the actual
-- failure mode here.
--
-- `(SELECT auth.uid())` rather than a bare call: the planner hoists it to an
-- InitPlan and evaluates it once per query instead of once per row.

DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'accounts',
    'categories',
    'transactions',
    'entries',
    'instruments',
    'prices',
    'fx_rates',
    'recurrences',
    'allocation_suggestions',
    'ingest_sources',
    'rule_settings'
  ]
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);

    EXECUTE format(
      'CREATE POLICY %I ON public.%I
         FOR ALL TO authenticated
         USING ("user_id" = (SELECT auth.uid()))
         WITH CHECK ("user_id" = (SELECT auth.uid()))',
      t || '_owner', t
    );

    -- Anonymous callers get no policy at all, so they see nothing. Revoking
    -- explicitly makes that intent legible rather than implied.
    EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
  END LOOP;
END
$rls$;
